import{_ as p,E as e,o as l,a as t,b as s,j as i,I as c,a6 as o}from"./chunks/framework.BNef1kRO.js";const k=JSON.parse('{"title":"电商详情主图从策划——落地1.0","description":"从需求输入到资产沉淀的五阶段 AI 商业视觉工作流。","frontmatter":{"title":"电商详情主图从策划——落地1.0","description":"从需求输入到资产沉淀的五阶段 AI 商业视觉工作流。","pageClass":"page-workflow-detail","status":"published"},"headers":[],"relativePath":"aigc/commercial-visual-system.md","filePath":"aigc/commercial-visual-system.md"}'),r={name:"aigc/commercial-visual-system.md"};function d(h,a,m,b,g,u){const n=e("MediaFrame");return l(),t("div",null,[a[0]||(a[0]=s("h1",{id:"电商详情主图从策划到落地-1-0",tabindex:"-1"},[i("电商详情主图从策划到落地 1.0 "),s("a",{class:"header-anchor",href:"#电商详情主图从策划到落地-1-0","aria-label":'Permalink to "电商详情主图从策划到落地 1.0"'},"​")],-1)),c(n,{src:"/aigc-2.jpg",alt:"发光电路组成的 AI 字样，代表电商视觉工作流中的数字生产环节",caption:"工作流把输入、变量、生成、判断与资产沉淀连接成一条可复盘的交付路径。",aspect:"16 / 9",eager:""}),a[1]||(a[1]=o(`<p>这是一份文章式流程手册。它像 Markdown 文档一样组织内容：有标题、段落、图解、案例和提示词；但最终是 HTML 文件，打开即可浏览，也适合后续作为飞书文章、团队规范或项目模板继续使用。</p><div class="language-Plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">Plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>一、完整项目逻辑</span></span>
<span class="line"><span>二、给 AI 的资料</span></span>
<span class="line"><span>三、主图沟通方法</span></span>
<span class="line"><span>四、详情页沟通方法</span></span>
<span class="line"><span>五、作品集沟通方法</span></span>
<span class="line"><span>六、反馈与验收</span></span></code></pre></div><h2 id="一、先让-ai-理解-这不是-出几张图-而是完整项目" tabindex="-1">一、先让 AI 理解：这不是“出几张图”，而是完整项目 <a class="header-anchor" href="#一、先让-ai-理解-这不是-出几张图-而是完整项目" aria-label="Permalink to &quot;一、先让 AI 理解：这不是“出几张图”，而是完整项目&quot;">​</a></h2><p>做电商视觉时，最容易犯的错误是直接让 AI 生成图片。这样往往能得到几张好看的图，但很难形成完整的项目逻辑。真正可复用的流程应该是：先分析产品，再策划主图，再策划详情页，最后整理成作品集。</p><p>图解展示：主图、详情页、作品集不是三个孤立任务，而是一个完整电商视觉项目。</p><blockquote><p>核心原则：主图负责吸引点击，详情页负责解释和转化，作品集负责展示设计能力和项目完整度。</p></blockquote><h2 id="二、开始前-需要给-ai-什么资料" tabindex="-1">二、开始前，需要给 AI 什么资料 <a class="header-anchor" href="#二、开始前-需要给-ai-什么资料" aria-label="Permalink to &quot;二、开始前，需要给 AI 什么资料&quot;">​</a></h2><p>AI 不怕信息多，怕信息模糊。你给 AI 的资料越完整，它越容易判断产品逻辑、卖点重点和图片结构。</p><p><strong>需要提供给AI的内容：</strong></p><p><strong>产品基础信息：</strong></p><p>产品名称、产品类型、平台、规格、型号、口味、颜色、容量、适用人群</p><p><strong>图片资料：</strong></p><p>包装图、产品图、细节图、使用场景图、竞品主图、竞品详情页</p><p><strong>卖点资料：</strong></p><p>成分、材质、技术、功能、场景、包装优势、定制优势、批发优势</p><p><strong>输出要求：</strong></p><p>主图数量、详情页屏数、作品集页数、语言、尺寸、视觉风格、平台规范</p><p><strong>产品基础信息：</strong></p><p>产品名称、产品类型、平台、规格、型号、口味、颜色、容量、适用人群</p><p><strong>图片资料：</strong></p><p>包装图、产品图、细节图、使用场景图、竞品主图、竞品详情页</p><p><strong>卖点资料：</strong></p><p>成分、材质、技术、功能、场景、包装优势、定制优势、批发优势</p><p><strong>输出要求：</strong></p><p>主图数量、详情页屏数、作品集页数、语言、尺寸、视觉风格、平台规范</p><p>注明：以上内容中，除过资料图片和输出要求之外，均可以提供文档，pdf等有产品信息的册子或者任意文案均可</p><div class="language-Plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">Plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>给 AI 的开场指令</span></span>
<span class="line"><span></span></span>
<span class="line"><span>你现在是一名电商视觉策划师和设计总监。请基于我提供的产品资料，先不要直接生成图片，先完成产品分析、卖点提炼、主图系统策划、详情页结构策划和作品集展示逻辑。要求所有输出都围绕平台转化，不要只做漂亮图。</span></span></code></pre></div><h2 id="三、主图怎么和-ai-沟通" tabindex="-1">三、主图怎么和 AI 沟通 <a class="header-anchor" href="#三、主图怎么和-ai-沟通" aria-label="Permalink to &quot;三、主图怎么和 AI 沟通&quot;">​</a></h2><p>主图要做成系统，而不是一组随机图片。一套完整主图至少要覆盖：包装、产品本体、核心卖点、使用场景、多角度、细节、系列和定制信息。</p><p>图解展示：这是主图的信息分区逻辑，不是固定版式；它帮助 AI 理解“画面各部分应该承担什么作用”。</p><h3 id="主图标准清单" tabindex="-1">主图标准清单 <a class="header-anchor" href="#主图标准清单" aria-label="Permalink to &quot;主图标准清单&quot;">​</a></h3><p>**1、**Hero 主图</p><p>第一眼建立产品定位，适合放包装、产品主体、核心卖点。</p><p>**2、**产品本体图</p><p>展示产品倒出、展开、微距、真实状态，避免只有包装。</p><p>**3、**成分 / 技术图</p><p>食品讲原料，工业品讲结构和原理，强调产品价值来源。</p><p>**4、**功能卖点图</p><p>一张图讲一到两个卖点，不要把所有功能堆在一起。</p><p>**5、**使用场景图</p><p>让客户知道何时用、哪里用、谁在用，建立真实代入。</p><p>**6、**细节 / 多角度图</p><p>展示材质、结构、包装、接口、切面、背面、侧面等。</p><h3 id="主图案例展示" tabindex="-1">主图案例展示 <a class="header-anchor" href="#主图案例展示" aria-label="Permalink to &quot;主图案例展示&quot;">​</a></h3><p><img src="https://my.feishu.cn/space/api/box/stream/download/asynccode/?code=NjAxNDY5NjlkM2Y1OTg4NDExNjBhOTBjZTQ5M2ViMmZfQXhCb2d6VHdpMVQ5c3FnV0ROdHp2dlFRN2pSNzh5QW5fVG9rZW46Smd5b2J6V0lQb0NvTTZ4U2NpUGNaMWRWblVmXzE3ODM3ODAwNTY6MTc4Mzc4MzY1Nl9WNA&amp;add_watermark=true&amp;scene_type=CCM" alt=""><img src="https://my.feishu.cn/space/api/box/stream/download/asynccode/?code=N2IwODU0NjZiODY5ZmQ1YjU0ZTBlMmY0ODJlZWM0MWZfVU5aRWw2akx3T3ZGS1I4Njlmb3JHREZReU1CMGNkNm1fVG9rZW46QlBEa2JPSVZ5bzhzZnd4UklIQmNPWWRPbnNkXzE3ODM3ODAwNTY6MTc4Mzc4MzY1Nl9WNA&amp;add_watermark=true&amp;scene_type=CCM" alt=""><img src="https://my.feishu.cn/space/api/box/stream/download/asynccode/?code=MmNmZjFjMDJiYzQ1ZDA0NDU2NzhhZmMyNTk2OGQxMWFfTVJwU0h3SkdHVnJLU2VSbGNYRldYc0J5eXhYTjBVckNfVG9rZW46QVFaYmJyTzVub0dFRnh4ZTVTVWNreEFqblhnXzE3ODM3ODAwNTY6MTc4Mzc4MzY1Nl9WNA&amp;add_watermark=true&amp;scene_type=CCM" alt=""></p><div class="language-Plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">Plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>主图提示词模板：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>角色：你是一名电商视觉策划师 + AI 图像提示词顾问。</span></span>
<span class="line"><span>任务：基于我提供的产品资料，先策划一套完整主图系统，包括风格限定，字体大小以及文案排版，版面样式确定策划，整个主图的字体需要好看，有调性，每一张主图的字体大小均保持一致；不要直接出图。</span></span>
<span class="line"><span>输出要求：</span></span>
<span class="line"><span>输出 6–10 张主图清单；</span></span>
<span class="line"><span>每张图必须包含：图片目标、画面结构、文案方向、AI 生成提示词、注意事项；</span></span>
<span class="line"><span>主图必须覆盖：Hero 主图、产品本体、成分/技术、功能卖点、使用场景、多角度、细节、系列/型号、包装/配件、B2B 定制；</span></span>
<span class="line"><span>不要只展示包装，必须有产品本体、场景、细节和转化卖点；</span></span>
<span class="line"><span>产品外观、包装结构、比例不能变形。</span></span></code></pre></div><h2 id="四、详情页怎么和-ai-沟通" tabindex="-1">四、详情页怎么和 AI 沟通 <a class="header-anchor" href="#四、详情页怎么和-ai-沟通" aria-label="Permalink to &quot;四、详情页怎么和 AI 沟通&quot;">​</a></h2><p>详情页不是海报合集，而是阅读链路。它要让客户从“不知道产品是什么”，一步步走到“理解产品、相信产品、知道怎么选择、愿意询盘”。</p><p>图解展示：详情页应按“认知层—信任层—转化层”组织内容。</p><h3 id="详情页基础结构" tabindex="-1">详情页基础结构 <a class="header-anchor" href="#详情页基础结构" aria-label="Permalink to &quot;详情页基础结构&quot;">​</a></h3><p><strong>详情首屏</strong>承接主图，建立产品第一印象。</p><p><strong>产品概述与卖点总览</strong>说明产品是什么、适合谁、解决什么问题，并用 4–6 个卖点快速建立价值。</p><p><strong>成分 / 材质 / 技术说明</strong>解释产品为什么有效、为什么专业，建立信任。</p><p><strong>功能、场景、细节展示</strong>通过功能拆解、场景代入、产品细节让客户理解使用价值。</p><p><strong>规格、包装、系列与询盘</strong>补充参数、包装、口味、型号、OEM、批发和联系引导。</p><h3 id="详情页案例展示" tabindex="-1">详情页案例展示 <a class="header-anchor" href="#详情页案例展示" aria-label="Permalink to &quot;详情页案例展示&quot;">​</a></h3><p><img src="https://my.feishu.cn/space/api/box/stream/download/asynccode/?code=NDQ5OTkwMzFkYzM1ZGQ3ODY4YjlkOWZjZjY2Y2EyNTZfQmRMRzBDdkVWeWZZaGtsV05SRThSRWZ2NWpYQnUyZXNfVG9rZW46TWg3VWJWR1lab0M4QUN4aEVSZ2NlTkRrbmpjXzE3ODM3ODAwNTY6MTc4Mzc4MzY1Nl9WNA&amp;add_watermark=true&amp;scene_type=CCM" alt=""></p><div class="language-Plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">Plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>详情页提示词模板</span></span>
<span class="line"><span></span></span>
<span class="line"><span>角色：你是一名电商详情页策划师。</span></span>
<span class="line"><span>任务：基于产品资料，策划一套连续转化逻辑的详情页，不要做成海报合集。</span></span>
<span class="line"><span>输出要求：</span></span>
<span class="line"><span>详情页建议 10–15 屏；</span></span>
<span class="line"><span>每一屏都要说明：屏幕目标、画面结构、文案、图片元素、AI 提示词、注意事项；</span></span>
<span class="line"><span>必须包含：详情首屏、产品概述、核心卖点总览、成分/材质/技术、功能卖点、产品细节、多角度、使用场景、规格/包装/系列、OEM/询盘收尾；</span></span>
<span class="line"><span>每一屏只讲一个重点，文字不要太密；</span></span>
<span class="line"><span>详情页要从产品认知逐步过渡到信任和询盘。</span></span></code></pre></div><h2 id="五、作品集怎么和-ai-沟通" tabindex="-1">五、作品集怎么和 AI 沟通 <a class="header-anchor" href="#五、作品集怎么和-ai-沟通" aria-label="Permalink to &quot;五、作品集怎么和 AI 沟通&quot;">​</a></h2><p>作品集不是把主图和详情页放进去就结束，而是要把项目变成一个“设计案例”。第三方看作品集时，既要看到结果，也要看到你的分析、策略、方法和价值。</p><p>图解展示：作品集的结构应像一个完整项目故事，而不是图片堆叠。</p><h3 id="作品集案例展示" tabindex="-1">作品集案例展示 <a class="header-anchor" href="#作品集案例展示" aria-label="Permalink to &quot;作品集案例展示&quot;">​</a></h3><p><img src="https://my.feishu.cn/space/api/box/stream/download/asynccode/?code=Njk0Njg0MTJiNWRlYjBiOTQ3M2I4YTY4NmFhNmQzNGZfWTRYMkF6MmlHVTNhRFJ5OFJma1p1VlE2TVlqdU15Z0hfVG9rZW46U2NlbmJZRUtHb1pqcFp4UGlscWNEbERCbmpoXzE3ODM3ODAwNTY6MTc4Mzc4MzY1Nl9WNA&amp;add_watermark=true&amp;scene_type=CCM" alt=""></p><p>案例：作品集封面 / 项目背景页。</p><p><img src="https://my.feishu.cn/space/api/box/stream/download/asynccode/?code=N2JkZDJlYTE0Y2JjZjgyMjBjYjZlMTdjNzRhNjFkZDJfZWhHZmh1OFVVblRaUVhacm4wWW1YcWF0UkJtakszQm1fVG9rZW46SldWdWJERWNmb255Rzd4YWdZbGMxSDE2bjBjXzE3ODM3ODAwNTY6MTc4Mzc4MzY1Nl9WNA&amp;add_watermark=true&amp;scene_type=CCM" alt=""></p><p>案例：主图系统展示页。</p><div class="language-Plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">Plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>作品集提示词模板</span></span>
<span class="line"><span></span></span>
<span class="line"><span>角色：你是一名高端作品集设计总监。</span></span>
<span class="line"><span>任务：把这个电商视觉项目整理成一套完整作品集。</span></span>
<span class="line"><span>输出要求：</span></span>
<span class="line"><span>作品集简约大气、有设计感、留白充足；</span></span>
<span class="line"><span>图片必须完整显示，不裁切主图、详情页和包装；</span></span>
<span class="line"><span>作品集结构包含：封面、项目背景、产品分析、核心卖点、视觉策略、包装优化、主图系统、主图拆解、详情页结构、详情页预览、重点页面展示、设计价值、流程复盘、最终成果；</span></span>
<span class="line"><span>每一页说明：标题、内容、图片摆放、说明文案、排版建议；</span></span>
<span class="line"><span>作品集重点展示设计逻辑，而不是简单堆图。</span></span></code></pre></div><h2 id="六、如何反馈与验收" tabindex="-1">六、如何反馈与验收 <a class="header-anchor" href="#六、如何反馈与验收" aria-label="Permalink to &quot;六、如何反馈与验收&quot;">​</a></h2><p>和 AI 反复优化时，不要只说“高级一点”“再优化一下”。要告诉 AI：哪里错了、什么不能改、要往哪个方向改。</p><p>**1、**指出问题：例如产品变形、包装错了、场景不足、文字太密、详情像海报。</p><p>**2、**强调保留：例如包装结构不变、产品颜色不变、文案语言不变、比例不变。</p><p>**3、**明确方向：例如增加多场景、多角度、细节、产品本体、B2B 信息。</p><div class="language-Plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">Plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>反馈模板:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>这版需要优化：</span></span>
<span class="line"><span>当前问题：【具体说明问题，例如产品变形、文案太密、场景不足、图片裁切、详情像海报】</span></span>
<span class="line"><span>必须保留：【产品外观/包装结构/配色/英文文案/尺寸比例】</span></span>
<span class="line"><span>优化方向：【增加场景/增加细节/减少文字/改成详情逻辑/图片完整展示】</span></span>
<span class="line"><span>输出要求：【平台、尺寸、语言、风格、是否单独出图】</span></span>
<span class="line"><span>注意：不要改变产品外观，不要裁切产品和包装，文案保持清晰，画面要符合平台使用场景。</span></span></code></pre></div><h3 id="最终检查" tabindex="-1">最终检查： <a class="header-anchor" href="#最终检查" aria-label="Permalink to &quot;最终检查：&quot;">​</a></h3><p>主图是否覆盖点击、产品本体、功能、场景、细节、系列和定制。</p><p>详情页是否从认知到信任再到转化，而不是海报拼接。</p><p>作品集是否展示了产品分析、视觉策略、设计系统和最终价值。</p>`,77))])}const M=p(r,[["render",d]]);export{k as __pageData,M as default};
